import numpy as np

def cholesky_decomposition(sigma):
    n = sigma.shape[0]
    L = np.zeros((n, n))
    for i in range(n):
        for j in range(i + 1):
            if i == j:
                L[i, j] = np.sqrt(sigma[i, i])
            else:
                sum = 0
                for k in range(j):
                    sum += L[i, k] * L[k, j]
                L[i, j] = (sigma[i, j] - sum) / L[j, j]

